import{_ as r,c as e,a2 as o,o as a}from"./chunks/framework.BQmytedh.js";const g=JSON.parse('{"title":"每个中国人心里都住着“孟子”｜如何借助孟子智慧待人处世","description":"","frontmatter":{},"headers":[],"relativePath":"哲思_人文_社科/博主_频道/岱川博士/鼓励好行为, 忽略坏行为.md","filePath":"哲思_人文_社科/博主_频道/岱川博士/鼓励好行为, 忽略坏行为.md","lastUpdated":1733938304000}'),s={name:"哲思_人文_社科/博主_频道/岱川博士/鼓励好行为, 忽略坏行为.md"};function n(_,t,i,l,p,d){return a(),e("div",null,t[0]||(t[0]=[o('<h1 id="每个中国人心里都住着-孟子-如何借助孟子智慧待人处世" tabindex="-1">每个中国人心里都住着“孟子”｜如何借助孟子智慧待人处世 <a class="header-anchor" href="#每个中国人心里都住着-孟子-如何借助孟子智慧待人处世" aria-label="Permalink to &quot;每个中国人心里都住着“孟子”｜如何借助孟子智慧待人处世&quot;">​</a></h1><p><a href="https://www.bilibili.com/video/BV1tr421W7vQ" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1tr421W7vQ</a></p><p>对我来说, 我认为孟子告诉我们如何最好地与他人相处. 很多时候我们想强迫别人为我们做事, 想强迫人们遵循我们喜欢的行为, 但是强迫人们做事通常是非常非常费力的. 而且通常不是很成功, 试图强迫人们做他们不想做的事, 通常是一种非常糟糕的说服方法, 说服人的最好方法, 我想是有点像孟子的理论: 我们发现良好行为的小种子，我们喜欢他人的小举动, 然后我们试着鼓励这些人, 引导这些人继续在他们自己生活中不断循环重复使用这些好的行为, 例如，这可以在教育孩子时使用.</p><p>同样，与你的配偶或与你同住的人或你的朋友, 有时他们会做一些让你心烦的事情, 有时他们会做你喜欢的事情, <strong>我们经常忽略我们喜欢的东西,</strong><strong>只是说 &quot;应该的&quot;,</strong><strong>但我们对不喜欢的事情感到愤怒,</strong><strong>然后批评,</strong> 这可能会产生非常负面的关系, <strong>也许更好的做事方式是忽略我们不喜欢的东西,</strong><strong>但是要大力赞扬和鼓励我们喜欢的事情,</strong> 然后如果这个人当然爱你, 他们可能会想哦哇, 当我这样做的时候，我的配偶真的很喜欢, 真的真的很开心, 所以我会做更多, 所以慢慢地这些好的行为会成为你们关系的主体, 你不必付出努力, 你不必争论, 因为你用了这些天然的萌芽, 这些善良的自然部分, 并培养它们，来改变他们生活中更大更大的一部分, 这些是我个人认为孟子的思想即使在非儒家背景下也能启发我们的方式.</p>',4)]))}const m=r(s,[["render",n]]);export{g as __pageData,m as default};
